        where_conditions = sql.split('where')[1].split('group by')[0].split('order by')[0]
        return 'and' in where_conditions or 'or' in where_conditions
    return True

def check(output: str, ctx: dict) -> bool:
    sql = extract_sql(output).lower()
    schema_columns = {col.lower() for table_cols in ctx['schema'].values() for col in table_cols}
    aggregates = re.findall(r'(count|avg|sum|max|min)\((.*?)\)', sql)
    return all(col.strip() in schema_columns or col.strip() == '*' for _, col in aggregates)

def check(output, ctx):
    try:
        import re
        sql = extract_sql(output)
        pairs = re.findall(r'([A-Za-z_][A-Za-z0-9_]*)\.?([A-Za-z_][A-Za-z0-9_]*)?\s*=\s*\'([^\']*)\'', sql)
        for a, b, lit in pairs:
            col = (b or a).lower()
            tables = [t for t, cols in ctx['schema'].items() if col in [c.lower() for c in cols]]
            if not tables or lit == '':
                continue
            exact_any = False
            ci_any = False
            for t in tables:
                try:
                    r1 = execute('SELECT 1 FROM "%s" WHERE "%s" = ? LIMIT 1' % (t, col)) if False else execute("SELECT 1 FROM \"%s\" WHERE \"%s\" = '%s' LIMIT 1" % (t, col, lit.replace("'", "''")))
                    if r1:
                        exact_any = True
                    r2 = execute("SELECT 1 FROM \"%s\" WHERE lower(\"%s\") = lower('%s') LIMIT 1" % (t, col, lit.replace("'", "''")))
                    if r2:
                        ci_any = True
                except Exception:
                    return True
            if not exact_any and ci_any:
                return False
        return True
    except Exception:
        return True

def check(output, ctx):
    try:
        import re
        q = ctx['question']
        sql = extract_sql(output)
        norm = lambda s: re.sub(r'[^a-z0-9]', '', s.lower())
        ns = norm(sql)
        for m in re.findall(r'"([^"]{2,60})"|\'([^\']{2,60})\'', q):
            lit = m[0] or m[1]
            nl = norm(lit)
            if len(nl) < 2:
                continue
            if nl not in ns:
                return False
        return True
    except Exception:
        return True

def check(output, ctx):
    try:
        import re
        q = ctx['question'].lower().strip()
        if not q.startswith('how many'):
            return True
        if re.search(r'\b(each|per|every|by|for all|respectively|different|and what|list|show|which)\b', q):
            return True
        rows = execute(extract_sql(output))
        return len(rows) <= 1
    except Exception:
        return True
